/**
 * Generates supabase/seed.sql from the typed catalogue.
 *
 *   npm run seed:sql        # writes supabase/seed.sql
 *   npm run seed:sql -- --print
 *
 * The generated file is idempotent: every statement upserts on the primary key,
 * so it can be re-run after editing lib/catalog/*.ts.
 */
import { categories, providers } from "../lib/catalog/providers";
import { exams } from "../lib/catalog/exams";
import { offers } from "../lib/catalog/offers";

const q = (value: string | null | undefined): string =>
  value === null || value === undefined ? "null" : `'${value.replace(/'/g, "''")}'`;

const arr = (values: readonly string[]): string =>
  `array[${values.map((value) => q(value)).join(", ")}]::text[]`;

const json = (value: unknown): string => `${q(JSON.stringify(value))}::jsonb`;

const date = (value: string | undefined): string =>
  value ? `${q(value)}::date` : "null";

const lines: string[] = [
  "-- ============================================================================",
  "-- Certitude — generated seed",
  "-- ============================================================================",
  "-- Generated by scripts/export-seed.ts from lib/catalog/*.ts. Do not edit by",
  "-- hand: change the TypeScript catalogue and run `npm run seed:sql`.",
  "--",
  "-- Idempotent: every statement upserts on the primary key.",
  "-- Apply with:  psql \"$DATABASE_URL\" -f supabase/seed.sql",
  "-- ============================================================================",
  "",
  "begin;",
  "",
];

lines.push("-- categories -----");
categories.forEach((category, index) => {
  lines.push(
    `insert into categories (slug, name, description, icon, sort_order)
values (${q(category.slug)}, ${q(category.name)}, ${q(category.description)}, ${q(category.icon)}, ${index})
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  icon = excluded.icon,
  sort_order = excluded.sort_order,
  is_active = true;`,
  );
});

lines.push("", "-- providers -----");
providers.forEach((provider) => {
  lines.push(
    `insert into providers (slug, name, short_name, mark, description, website_url, accent, categories)
values (${q(provider.slug)}, ${q(provider.name)}, ${q(provider.shortName)}, ${q(provider.mark)}, ${q(provider.description)}, ${q(provider.websiteUrl)}, ${q(provider.accent)}, ${arr(provider.categories)})
on conflict (slug) do update set
  name = excluded.name,
  short_name = excluded.short_name,
  mark = excluded.mark,
  description = excluded.description,
  website_url = excluded.website_url,
  accent = excluded.accent,
  categories = excluded.categories;`,
  );
});

lines.push("", "-- exams -----");
exams.forEach((exam) => {
  lines.push(
    `insert into exams (slug, code, name, provider_slug, level, category, summary, description, duration_minutes, question_count, passing_score, languages, official_price_inr, official_price_usd, retire_at, exam_url, audience, study_hours, skills, faqs, popularity, is_active)
values (${q(exam.slug)}, ${q(exam.code)}, ${q(exam.name)}, ${q(exam.providerSlug)}, ${q(exam.level)}, ${q(exam.category)}, ${q(exam.summary)}, ${q(exam.description)}, ${exam.durationMinutes}, ${exam.questionCount}, ${q(exam.passingScore)}, ${arr(exam.languages)}, ${exam.officialPriceInr}, ${exam.officialPriceUsd}, ${date(exam.retireAt)}, ${q(exam.examUrl)}, ${q(exam.audience)}, ${exam.studyHours}, ${arr(exam.skills)}, ${json(exam.faqs)}, ${exam.popularity}, true)
on conflict (slug) do update set
  code = excluded.code,
  name = excluded.name,
  provider_slug = excluded.provider_slug,
  level = excluded.level,
  category = excluded.category,
  summary = excluded.summary,
  description = excluded.description,
  duration_minutes = excluded.duration_minutes,
  question_count = excluded.question_count,
  passing_score = excluded.passing_score,
  languages = excluded.languages,
  official_price_inr = excluded.official_price_inr,
  official_price_usd = excluded.official_price_usd,
  retire_at = excluded.retire_at,
  exam_url = excluded.exam_url,
  audience = excluded.audience,
  study_hours = excluded.study_hours,
  skills = excluded.skills,
  faqs = excluded.faqs,
  popularity = excluded.popularity,
  is_active = true;`,
  );
});

lines.push("", "-- offers -----");
offers.forEach((offer) => {
  lines.push(
    `insert into offers (id, exam_slug, supplier_name, supply_status, price_inr, compare_at_inr, region, eligibility, delivery_estimate, voucher_validity_days, last_verified_at, notes, is_active)
values (${q(offer.id)}, ${q(offer.examSlug)}, ${q(offer.supplierName)}, ${q(offer.supplyStatus)}, ${offer.priceInr}, ${offer.compareAtInr}, ${q(offer.region)}, ${q(offer.eligibility)}, ${q(offer.deliveryEstimate)}, ${offer.voucherValidityDays}, ${q(offer.lastVerifiedAt)}::timestamptz, ${q(offer.notes)}, true)
on conflict (id) do update set
  exam_slug = excluded.exam_slug,
  supplier_name = excluded.supplier_name,
  supply_status = excluded.supply_status,
  price_inr = excluded.price_inr,
  compare_at_inr = excluded.compare_at_inr,
  region = excluded.region,
  eligibility = excluded.eligibility,
  delivery_estimate = excluded.delivery_estimate,
  voucher_validity_days = excluded.voucher_validity_days,
  last_verified_at = excluded.last_verified_at,
  notes = excluded.notes,
  is_active = true;`,
  );
});

lines.push("", "commit;", "");

process.stdout.write(lines.join("\n"));
